output_text:
Here's a fully functional HTML document for a team notes app called Notebook. It includes a three-pane workspace with note lists, markdown rendering, comments, and live search.
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Notebook — team notes</title>
<style>
  :root{
    --bg:#fff; --panel:#fafafa; --line:#ececf0; --line-2:#e2e2e8;
    --text:#18181b; --muted:#71717a; --faint:#a1a1aa;
    --accent:#6366f1; --accent-soft:#eef2ff;
    --radius:10px;
  }
  *{box-sizing:border-box}
  html,body{height:100%;margin:0}
  body{
    font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Inter,Roboto,Helvetica,Arial,sans-serif;
    font-size:13.5px; line-height:1.55; color:var(--text); background:var(--bg);
    -webkit-font-smoothing:antialiased; overflow:hidden;
  }
  button{font:inherit;color:inherit;background:none;border:none;cursor:pointer}
  input,textarea,select{font:inherit;color:inherit}
  ::-webkit-scrollbar{width:10px;height:10px}
  ::-webkit-scrollbar-thumb{background:#dcdce2;border-radius:99px;border:3px solid transparent;background-clip:content-box}
  ::-webkit-scrollbar-thumb:hover{background:#c4c4cc;background-clip:content-box;border:3px solid transparent}
  ::-webkit-scrollbar-track{background:transparent}

  .app{display:grid;grid-template-columns:236px 304px 1fr;height:100vh}

  /* ---------- Sidebar ---------- */
  .sb{background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column;overflow:hidden}
  .sb-head{display:flex;align-items:center;gap:10px;padding:16px 16px 14px}
  .logo{width:28px;height:28px;border-radius:8px;background:linear-gradient(135deg,#6366f1,#8b5cf6);
        color:#fff;display:grid;place-items:center;font-weight:700;font-size:13px;flex:none;
        box-shadow:0 2px 6px rgba(99,102,241,.35)}
  .ws{font-weight:640;font-size:13.5px;letter-spacing:-.01em}
  .ws-sub{font-size:11.5px;color:var(--faint);margin-top:-2px}
  .nav{padding:0 8px}
  .nav-item{display:flex;align-items:center;gap:9px;padding:6.5px 8px;border-radius:7px;
            width:100%;text-align:left;color:#3f3f46;font-size:13px;transition:background .12s}
  .nav-item svg{width:15px;height:15px;flex:none;opacity:.7}
  .nav-item:hover{background:#f0f0f3}
  .nav-item.on{background:#eceafd;color:#4338ca;font-weight:560}
  .nav-item.on svg{opacity:1;color:#6366f1}
  .nav-item .count{margin-left:auto;font-size:11.5px;color:var(--faint);font-variant-numeric:tabular-nums}
  .nav-item.on .count{color:#818cf8}
  .sb-section{padding:20px 16px 0;flex:1;overflow-y:auto;min-height:0}
  .sb-title{font-size:11px;font-weight:640;text-transform:uppercase;letter-spacing:.06em;
            color:var(--faint);margin-bottom:8px}
  .tag-row{display:flex;align-items:center;gap:8px;padding:5px 8px;margin:0 -8px;border-radius:7px;
           cursor:pointer;color:#52525b;font-size:12.5px}
  .tag-row:hover{background:#f0f0f3}
  .tag-row.on{background:#eceafd;color:#4338ca;font-weight:560}
  .tag-dot{width:7px;height:7px;border-radius:99px;flex:none}
  .tag-row .count{margin-left:auto;font-size:11px;color:var(--faint)}
  .sb-foot{border-top:1px solid var(--line);padding:10px 14px;display:flex;align-items:center;gap:9px}
  .sb-foot .nm{font-size:12.5px;font-weight:560}
  .sb-foot .rl{font-size:11px;color:var(--faint);margin-top:-1px}

  /* ---------- Avatars ---------- */
  .av{display:inline-grid;place-items:center;border-radius:99px;background:var(--c);
      color:#fff;font-weight:600;flex:none;letter-spacing:-.02em;user-select:none}
  .av-stack{display:flex}
  .av-stack .av{border:2px solid #fff;margin-left:-7px}
  .av-stack .av:first-child{margin-left:0}

  /* ---------- List pane ---------- */
  .lp{background:#fff;border-right:1px solid var(--line);display:flex;flex-direction:column;overflow:hidden}
  .lp-head{display:flex;align-items:flex-start;justify-content:space-between;padding:16px 16px 10px}
  .lp-head h1{margin:0;font-size:15px;font-weight:660;letter-spacing:-.015em}
  .lp-count{font-size:11.5px;color:var(--faint);margin-top:2px}
  .new{width:26px;height:26px;border-radius:7px;background:var(--accent);color:#fff;display:grid;
       place-items:center;font-size:17px;line-height:1;box-shadow:0 1px 4px rgba(99,102,241,.4);
       transition:transform .12s, box-shadow .12s}
  .new:hover{transform:translateY(-1px);box-shadow:0 3px 9px rgba(99,102,241,.45)}
  .new:active{transform:translateY(0)}
  .search-wrap{margin:0 14px 8px;position:relative;display:flex;align-items:center}
  .search-wrap svg{position:absolute;left:9px;width:14px;height:14px;color:var(--faint);pointer-events:none}
  #search{width:100%;padding:7px 44px 7px 29px;border:1px solid var(--line-2);border-radius:8px;
          background:#fafafa;font-size:12.5px;outline:none;transition:.15s}
  #search:focus{background:#fff;border-color:#c7c7f5;box-shadow:0 0 0 3px rgba(99,102,241,.1)}
  #search::placeholder{color:var(--faint)}
  kbd{position:absolute;right:7px;font-size:10px;font-family:inherit;color:var(--faint);
      border:1px solid var(--line-2);border-radius:4px;padding:1px 4px;background:#fff}
  .list{flex:1;overflow-y:auto;padding:2px 8px 20px}

  .item{padding:9px 10px 10px;border-radius:9px;cursor:pointer;margin-bottom:1px;
        border:1px solid transparent;transition:background .1s}
  .item:hover{background:#f7f7f9}
  .item.on{background:#f4f4ff;border-color:#e4e2fd}
  .item-top{display:flex;align-items:center;gap:6px}
  .item-title{font-weight:580;font-size:13px;letter-spacing:-.01em;white-space:nowrap;
              overflow:hidden;text-overflow:ellipsis;flex:1}
  .item.on .item-title{color:#3730a3}
  .pin-ic{width:12px;height:12px;color:#6366f1;flex:none}
  .item-prev{font-size:12px;color:var(--muted);margin-top:2px;display:-webkit-box;
             -webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.45}
  .item-foot{display:flex;align-items:center;gap:6px;margin-top:7px;font-size:11px;color:var(--faint)}
  .item-foot .sep{opacity:.5}
  .mini-tag{font-size:10.5px;background:#f1f1f4;color:#5b5b66;padding:1px 6px;border-radius:99px;
            white-space:nowrap}
  .cmt-ic{display:inline-flex;align-items:center;gap:3px;margin-left:auto}
  .cmt-ic svg{width:11px;height:11px}
  .empty{padding:36px 20px;text-align:center;color:var(--faint);font-size:12.5px;line-height:1.6}

  /* ---------- Editor pane ---------- */
  .ed{overflow-y:auto;background:#fff;display:flex;flex-direction:column}
  .ed-empty{margin:auto;text-align:center;color:var(--faint);max-width:280px;padding:40px}
  .ed-empty .big{font-size:32px;margin-bottom:10px;opacity:.35}

  .ed-inner{max-width:760px;width:100%;margin:0 auto;padding:28px 40px 60px;flex:1}
  .ed-head{border-bottom:1px solid var(--line);padding-bottom:14px;margin-bottom:20px}
  .ed-titlerow{display:flex;align-items:flex-start;gap:8px}
  .ed-title{flex:1;border:none;outline:none;font-size:23px;font-weight:680;letter-spacing:-.025em;
            line-height:1.3;padding:2px 0;background:transparent;resize:none;overflow:hidden;
            font-family:inherit;width:100%}
  .ed-title::placeholder{color:#d4d4d8}
  .icon-btn{width:28px;height:28px;border-radius:7px;display:grid;place-items:center;
            color:var(--faint);flex:none;transition:.12s}
  .icon-btn:hover{background:#f4f4f6;color:#3f3f46}
  .icon-btn.on{color:var(--accent);background:var(--accent-soft)}
  .icon-btn.danger:hover{background:#fef2f2;color:#dc2626}
  .icon-btn svg{width:15px;height:15px}

  .ed-meta{display:flex;align-items:center;gap:9px;margin-top:12px;flex-wrap:wrap;
           font-size:11.5px;color:var(--faint)}
  .ed-meta .nm{color:#52525b;font-weight:540}
  .badge{font-size:10.5px;padding:1.5px 7px;border-radius:99px;background:#f1f1f4;color:#52525b;
         font-weight:540;display:inline-flex;align-items:center;gap:4px}
  .badge.team{background:#eef2ff;color:#4338ca}
  .badge.shared{background:#ecfdf5;color:#047857}
  .badge.private{background:#fef3c7;color:#92400e}
  .tag-pill{font-size:10.5px;padding:1.5px 7px;border-radius:99px;background:#f4f4f6;color:#5b5b66}
  .save-dot{width:5px;height:5px;border-radius:99px;background:#22c55e;opacity:0;transition:opacity .3s}
  .save-dot.show{opacity:1}

  .share-row{display:flex;align-items:center;gap:6px;margin-top:10px;flex-wrap:wrap}
  .chip{font-size:11.5px;padding:3px 9px;border-radius:99px;border:1px solid var(--line-2);
        color:#52525b;display:inline-flex;align-items:center;gap:5px;transition:.12s}
  .chip:hover{border-color:#c7c7f5;background:#fafaff}
  .chip.on{background:var(--accent-soft);border-color:#c7c7f5;color:#4338ca}

  /* Markdown view */
  .md-view{cursor:text;min-height:180px;font-size:14px;line-height:1.7;color:#27272a}
  .md-view:empty::before{content:'Start writing…';color:#d4d4d8}
  .md-view h1{font-size:19px;font-weight:660;letter-spacing:-.02em;margin:22px 0 8px}
  .md-view h1:first-child{margin-top:0}
  .md-view h2{font-size:16px;font-weight:640;letter-spacing:-.015em;margin:20px 0 7px}
  .md-view h3{font-size:14px;font-weight:640;margin:16px 0 5px}
  .md-view p{margin:0 0 10px}
  .md-view ul{margin:0 0 12px;padding-left:20px}
  .md-view li{margin:3px 0}
  .md-view ul.checks{list-style:none;padding-left:2px}
  .md-view ul.checks li{display:flex;align-items:flex-start;gap:8px;cursor:pointer;
                        padding:1px 0;border-radius:5px}
  .md-view ul.checks li:hover{background:#fafafa}
  .md-view ul.checks li.done>span:last-child{color:var(--faint);text-decoration:line-through}
  .cb{width:14px;height:14px;border:1.5px solid #d4d4d8;border-radius:4px;flex:none;margin-top:4px;
      display:grid;place-items:center;transition:.12s}
  .cb.checked{background:var(--accent);border-color:var(--accent)}
  .cb.checked::after{content:'';width:3.5px;height:7px;border:solid #fff;border-width:0 1.8px 1.8px 0;
                     transform:rotate(42deg) translate(-1px,-1px)}
  .md-view blockquote{margin:0 0 12px;padding:2px 0 2px 14px;border-left:2.5px solid #ddd6fe;
                      color:#52525b;font-style:italic}
  .md-view code{background:#f4f4f6;padding:1.5px 5px;border-radius:4px;font-size:12.5px;
                font-family:ui-monospace,SFMono-Regular,Menlo,monospace}
  .md-view pre{background:#fafafa;border:1px solid var(--line);border-radius:9px;padding:12px 14px;
               overflow-x:auto;margin:0 0 14px}
  .md-view pre code{background:none;padding:0;font-size:12.5px;line-height:1.6}
  .md-view strong{font-weight:640}
  .mention{color:#4338ca;background:var(--accent-soft);border-radius:4px;padding:0 3px;font-weight:540}

  #bodyInput{width:100%;border:none;outline:none;resize:none;font-size:14px;line-height:1.7;
             font-family:inherit;color:#27272a;min-height:300px;padding:0;background:transparent;
             overflow:hidden}

  /* Comments */
  .comments{border-top:1px solid var(--line);margin-top:32px;padding-top:20px}
  .comments h3{font-size:12px;font-weight:660;text-transform:uppercase;letter-spacing:.06em;
               color:var(--faint);margin:0 0 14px;display:flex;align-items:center;gap:7px}
  .comments h3 .num{background:#f1f1f4;color:#52525b;border-radius:99px;padding:0 6px;
                    font-size:10.5px;letter-spacing:0}
  .comment{display:flex;gap:10px;margin-bottom:14px}
  .c-body{flex:1;min-width:0}
  .c-head{display:flex;align-items:baseline;gap:7px;font-size:12px;color:var(--faint)}
  .c-head strong{color:var(--text);font-weight:600;font-size:12.5px}
  .c-text{font-size:13px;color:#3f3f46;margin-top:2px;white-space:pre-wrap;word-wrap:break-word}
  .c-new{display:flex;gap:10px;margin-top:6px}
  .c-new textarea{flex:1;border:1px solid var(--line-2);border-radius:9px;padding:8px 11px;
                  font-size:12.5px;outline:none;resize:none;min-height:38px;max-height:180px;
                  transition:.15s;font-family:inherit;line-height:1.5}
  .c-new textarea:focus{border-color:#c7c7f5;box-shadow:0 0 0 3px rgba(99,102,241,.1)}
  .c-new textarea::placeholder{color:var(--faint)}
  .c-actions{display:flex;align-items:center;gap:8px;margin-top:7px}
  .btn{background:var(--accent);color:#fff;border-radius:7px;padding:5px 12px;font-size:12px;
       font-weight:560;transition:.12s}
  .btn:hover{background:#4f46e5}
  .btn:disabled{opacity:.4;cursor:default}
  .hint{font-size:11px;color:var(--faint)}
  .muted{color:var(--faint)}
  .small{font-size:12px}

  @media (max-width:1100px){ .app{grid-template-columns:212px 264px 1fr} .ed-inner{padding:24px 28px 60px} }
  @media (max-width:860px){ .app{grid-template-columns:236px 1fr} .lp{display:none} }
</style>
</head>
<body>
<div class="app">
  <aside class="sb">
    <div class="sb-head">
      <div class="logo">N</div>
      <div>
        <div class="ws">Northwind</div>
        <div class="ws-sub">Team workspace</div>
      </div>
    </div>
    <nav class="nav" id="nav"></nav>
    <div class="sb-section">
      <div class="sb-title">Tags</div>
      <div id="tags"></div>
    </div>
    <div class="sb-foot" id="meFoot"></div>
  </aside>

  <section class="lp">
    <div class="lp-head">
      <div>
        <h1 id="lpTitle">All notes</h1>
        <div class="lp-count" id="lpCount"></div>
      </div>
      <button class="new" id="newBtn" title="New note">+</button>
    </div>
    <div class="search-wrap">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
           stroke-linecap="round" stroke-linejoin="round">
        <circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/>
      </svg>
      <input id="search" placeholder="Search notes…" autocomplete="off" spellcheck="false">
      <kbd>⌘K</kbd>
    </div>
    <div class="list" id="list"></div>
  </section>

  <main class="ed" id="ed"></main>
</div>

<script>
/* =========================================================
   Team data
   ========================================================= */
const USERS = [
  { id:'u1', name:'Ada Chen',        color:'#6366f1' },
  { id:'u2', name:'Marcus Webb',     color:'#ec4899' },
  { id:'u3', name:'Priya Raman',     color:'#f59e0b' },
  { id:'u4', name:'Tom Okafor',      color:'#10b981' },
  { id:'u5', name:'Sofia Lindqvist', color:'#0ea5e9' },
];
const ME = 'u1';
const user = id => USERS.find(u => u.id === id) || { id, name:'Unknown', color:'#a1a1aa' };

const H = 3600e3, D = 24 * H, now = Date.now();

function seed() {
  return [
    {
      id:'n1',
      title:'Q3 launch — rollout plan',
      body:`# Rollout plan\n\nWe ship **v2.4** to 10% of workspaces on Sept 2, then ramp over two weeks.\n\n## Phases\n- [x] Feature freeze\n- [x] QA sign-off on the new editor\n- [ ] Staged rollout to 10% — @Marcus Webb owns the dashboards\n- [ ] Ramp to 50%\n- [ ] Full availability + changelog post\n\n> Rollback path: flip \`launch_v24\` in the flag service. No deploy needed.\n\n## Owners\n- Comms — @Priya Raman\n- Support macros — @Tom Okafor\n- Docs — me\n`,
      authorId:'u1', visibility:'team', sharedWith:[],
      tags:['launch','planning'], pinned:true,
      createdAt: now - 6*D, updatedAt: now - 2*H,
      comments:[
        { id:'c1', authorId:'u2', text:'Dashboards are ready. I\'ll wire up the ramp alerts today so we get paged if activation dips more than 4%.', createdAt: now - 95*60000 },
        { id:'c2', authorId:'u3', text:'@Ada Chen do we have a changelog draft? I can write the top section if you want.', createdAt: now - 42*60000 },
      ],
    },
    {
      id:'n2',
      title:'Design review — Aug 14',
      body:`## Decisions\n- Sidebar collapses to icons under 900px\n- Empty states get illustrations — **not** icons\n- Keep the 12px radius scale, drop the 16px one\n\n## Open questions\n- [ ] Do we need a dark mode round before launch?\n- [x] Confirm the type scale with @Priya Raman\n- [ ] Motion spec for the drawer\n\n> Next review: Thursday 10:00, same room.\n`,
      authorId:'u3', visibility:'team', sharedWith:[],
      tags:['design'], pinned:false,
      createdAt: now - 3*D, updatedAt: now - 5*H,
      comments:[
        { id:'c3', authorId:'u1', text:'The illustration call is right. Icons made the empty states feel like errors.', createdAt: now - 4*H },
        { id:'c4', authorId:'u5', text:'I can take the motion spec — will have something by Wednesday.', createdAt: now - 3*H },
      ],
    },
    {
      id:'n3',
      title:'New engineer onboarding checklist',
      body:`## Day 1\n- [x] Laptop + accounts provisioned\n- [x] Added to #eng and #eng-random\n- [ ] Pair with buddy on a first PR\n- [ ] Read the architecture doc\n\n## Week 1\n- [ ] Ship a "good first issue"\n- [ ] Coffee with each teammate\n- [ ] Local dev environment running\n\n## Buddy rotation\n- Q3: @Marcus Webb, @Tom Okafor\n- Q4: @Priya Raman, @Sofia Lindqvist\n`,
      authorId:'u4', visibility:'team', sharedWith:[],
      tags:['process','onboarding'], pinned:false,
      createdAt: now - 12*D, updatedAt: now - 1*D,
      comments:[
        { id:'c5', authorId:'u1', text:'Adding a "shadow an on-call rotation" item — new folks found that the most useful thing last quarter.', createdAt: now - 26*H },
      ],
    },
    {
      id:'n4',
      title:'API v2 migration guide',
      body:`# Migrating to API v2\n\nAll v1 endpoints stay live until **March 1**. The shape changes are mostly additive.\n\n## Breaking changes\n1. \`GET /users\` now paginates — pass \`?cursor=\`\n2. Errors return \`{ error: { code, message } }\` instead of a bare string\n3. Rate limit headers renamed to \`X-RateLimit-*\`\n\n\`\`\`\ncurl https://api.example.com/v2/users?cursor=abc \\\n  -H "Authorization: Bearer $TOKEN"\n\`\`\`\n\n## Timeline\n- [x] v2 in production\n- [ ] Client SDKs updated\n- [ ] Deprecation emails sent\n- [ ] v1 shutoff\n`,
      authorId:'u2', visibility:'team', sharedWith:[],
      tags:['engineering'], pinned:false,
      createdAt: now - 9*D, updatedAt: now - 2*D,
      comments:[
        { id:'c6', authorId:'u4', text:'I added the curl example. Worth calling out that the cursor is opaque — people keep trying to parse it.', createdAt: now - 2*D },
      ],
    },
    {
      id:'n5',
      title:'Incident postmortem — 8/09 latency spike',
      body:`## Summary\np99 latency went from 240ms to 4.1s for 38 minutes. Roughly 2% of requests failed.\n\n## Timeline (UTC)\n- **14:02** — Deploy of the \`cache-warmup\` change\n- **14:07** — Alerts fire, @Tom Okafor takes on-call\n- **14:19** — Rollback initiated\n- **14:40** — Metrics back to baseline\n\n## Root cause\nThe warmup job ran synchronously on boot and saturated the connection pool, so normal traffic queued behind it.\n\n## Action items\n- [x] Roll back the change\n- [ ] Add a connection-pool saturation alert\n- [ ] Make warmup asynchronous\n- [ ] Add a staging soak test before deploys\n`,
      authorId:'u4', visibility:'team', sharedWith:[],
      tags:['engineering','postmortem'], pinned:false,
      createdAt: now - 5*D, updatedAt: now - 4*D,
      comments:[
        { id:'c7', authorId:'u2', text:'The saturation alert is the highest-value item here. I\'ll pick it up this sprint.', createdAt: now - 4*D + 2*H },
        { id:'c8', authorId:'u1', text:'Nice writeup — blameless and specific. Sharing with the wider org.', createdAt: now - 3*D },
      ],
    },
    {
      id:'n6',
      title:'Customer feedback — Acme Corp',
      body:`Call with Dana R. (VP Engineering) on Tuesday.\n\n## What they love\n- Search is noticeably faster than their old tool\n- Comment threads right on the note\n\n## What's blocking renewal\n- No SCIM provisioning — they'd manage 400 seats by hand\n- They need a CSV export for compliance\n- SSO with Okta is "table stakes"\n\n## Next step\n@Marcus Webb to scope SCIM. Target: proposal by Friday.\n`,
      authorId:'u1', visibility:'shared', sharedWith:['u2','u3'],
      tags:['customer'], pinned:false,
      createdAt: now - 2*D, updatedAt: now - 20*H,
      comments:[
        { id:'c9', authorId:'u3', text:'Their compliance team asked me the same thing at the conference. This isn\'t just Acme.', createdAt: now - 19*H },
        { id:'c10', authorId:'u2', text:'Scoping now. Rough estimate is two weeks of work — I\'ll have real numbers Friday.', createdAt: now - 6*H },
      ],
    },
    {
      id:'n7',
      title:'Weekly sync agenda',
      body:`Every Monday 9:30, 25 minute hard stop.\n\n1. Metrics check — @Marcus Webb (5m)\n2. Blockers round-robin (10m)\n3. One demo (5m)\n4. Parking lot (5m)\n\n## This week\n- Launch ramp decision\n- Hiring: two onsite debriefs\n- @Priya Raman walks through the new editor\n\n> Keep it to 25. If we need more, it goes offline.\n`,
      authorId:'u5', visibility:'team', sharedWith:[],
      tags:['meetings'], pinned:false,
      createdAt: now - 1*D, updatedAt: now - 70*60000,
      comments:[],
    },
  ];
}

/* =========================================================
   State
   ========================================================= */
const KEY = 'teamnotes.v1';
let notes, activeId, filter = 'all', tagFilter = null, query = '';

try {
  const raw = localStorage.getItem(KEY);
  notes = raw ? JSON.parse(raw) : seed();
} catch { notes = seed(); }
