    </div>
  </div>

  <!-- Settings Modal -->
  <div class="modal-overlay" id="modalOverlay">
    <div class="modal">
      <div class="modal-header">
        <h2>Timer Settings</h2>
        <button class="close-modal" id="closeSettingsBtn">&times;</button>
      </div>
      <form id="settingsForm">
        <div class="form-group">
          <label for="workInput">Work (minutes)</label>
          <input type="number" id="workInput" min="1" max="120" required />
        </div>
        <div class="form-group">
          <label for="shortInput">Short Break (minutes)</label>
          <input type="number" id="shortInput" min="1" max="60" required />
        </div>
        <div class="form-group">
          <label for="longInput">Long Break (minutes)</label>
          <input type="number" id="longInput" min="1" max="60" required />
        </div>
